SELECT
    (
        SELECT COUNT(*)
        FROM allowance_request ar
        WHERE ar.child_id = #{childId}
          AND ar.status = 'PENDING'
    ) AS pendingAllowanceRequestCount,


            (
                SELECT COUNT(*)
                FROM account_transaction tx
                WHERE tx.financial_account_id = #{accountId}
                  AND tx.occurred_at >= #{startOccurredAt}
                  AND tx.occurred_at < #{endOccurredAtExclusive}
            )


            0


    AS currentMonthTransactionCount
